    public Diagnosis testCreate() throws Throwable {
    Diagnosis entity = null;

    LOGGER.info( "DiagnosisTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Diagnosis");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Diagnosis" );

    try {
        entity = service.createDiagnosis( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getDiagnosisId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Diagnosis with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

