    /**
     * Tests getting all Diagnosiss.
     *
     * @return    Collection
     */
    public List<Diagnosis> testGetAll() throws Throwable {
    LOGGER.info( "DiagnosisTest:testGetAll() - Retrieving Collection of Diagnosiss:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Diagnosis : " );
    List<Diagnosis> collection  = null;

    try {
        // call the static get method on the DiagnosisService
        collection = service.getAllDiagnosis();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Diagnosis currEntity  = null;
            Iterator<Diagnosis> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDiagnosisId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

